import{af as s,z as t,J as a,ab as i}from"./chunks/framework.BQKxTN4d.js";const g=JSON.parse('{"title":"Tracking sessions","description":"","frontmatter":{"order":35},"headers":[],"relativePath":"devices/api/protocol/sessions.md","filePath":"devices/api/protocol/sessions.md"}'),n={name:"devices/api/protocol/sessions.md"};function r(o,e,d,c,p,h){return t(),a("div",{"data-pagefind-body":!0,"data-pagefind-meta":"date:1795016548000"},[...e[0]||(e[0]=[i('<h1 id="tracking-sessions" tabindex="-1">Tracking sessions <a class="header-anchor" href="#tracking-sessions" aria-label="Permalink to &quot;Tracking sessions&quot;">​</a></h1><p>A tracking session is a buffered group of V3 messages produced for one tracking upload. It is separate from a transport connection: a connection can carry multiple sessions, and a session is identified by its protocol session ID.</p><p>Firmware begins a session with <strong>Session Start</strong> (message type 21). Its message ID is the session ID; firmware adds that same ID as the <code>Session ID</code> header (field 20) to the start and each message accepted into the session. The start can include the reset code, alert sensor value, last send reason, last error, and an encryption public key when initiating the key exchange.</p><p>Firmware closes the group with <strong>Session End</strong> (message type 22). Its <code>Message Count</code> (field 20) includes the start and preceding messages, but excludes the end message. Firmware queues the completed buffer for tracking storage after the end is added; this describes local buffering, not server receipt or acknowledgement.</p><p>On the server, gingin can collect bounded session messages and attach their raw bytes to Session End in the <code>Received With</code> header (field 103). This bundle is optional: it can be disabled, and downstream processing skips the bundle when it is absent. This is server-side ingestion behavior, not a guarantee that every transport or server provides the field.</p><p>The message definitions remain marked hidden from the public protocol message reference in the protocol source. Their names and fields above describe current firmware behavior; the server behavior is specific to gingin.</p>',6)])])}const m=s(n,[["render",r]]);export{g as __pageData,m as default};
